-- 仅供 Login Lockout 集成测试：每个用例一个独立账号，失败计数与锁定互不影响。插入须可重复执行。
-- 身份均为演示租户成员、密码与演示身份相同；运营账号的密码与演示运营相同。
INSERT INTO identity (id, account, email, display_name, password_hash)
SELECT CAST(v.id AS uuid), v.account, v.account || '@example.com', v.account, i.password_hash
FROM identity i CROSS JOIN (VALUES
    ('019a0110-0000-7000-8000-000000000501', 'lock-known'),
    ('019a0110-0000-7000-8000-000000000502', 'lock-expiry'),
    ('019a0110-0000-7000-8000-000000000503', 'lock-mfa'),
    ('019a0110-0000-7000-8000-000000000504', 'lock-mfa-token'),
    ('019a0110-0000-7000-8000-000000000505', 'lock-change'),
    ('019a0110-0000-7000-8000-000000000506', 'lock-reset'),
    ('019a0110-0000-7000-8000-000000000507', 'lock-ip'),
    ('019a0110-0000-7000-8000-000000000508', 'lock-regen'),
    ('019a0110-0000-7000-8000-000000000509', 'lock-unbind'),
    ('019a0110-0000-7000-8000-00000000050a', 'lock-id-change')) AS v (id, account)
WHERE i.account = 'demo'
ON CONFLICT DO NOTHING;
